// domain/Order.ts
export class Order {
  public id: string;
  public status: string;
  public lineItems: LineItem[];
  public totalAmount: number;
  public approvedBy?: string;
  public confirmedAt?: Date;
  public cancelledAt?: Date;

  setStatus(s: string) { this.status = s; }
  setApprovedBy(userId: string) { this.approvedBy = userId; }
  setConfirmedAt(d: Date) { this.confirmedAt = d; }
}

// application/OrderService.ts — confirmOrder method
async confirmOrder(orderId: string, userId: string): Promise<void> {
  const order = await this.repo.findById(orderId);
  if (order.status !== 'pending') throw new Error('Not pending');
  if (order.totalAmount > 10000 && !order.approvedBy)
    throw new Error('High-value orders require approval');
  order.setStatus('confirmed');
  order.setApprovedBy(userId);
  order.setConfirmedAt(new Date());
  await this.repo.save(order);
}
